using System.Data;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using MediDesk.Common.Contracts.Catalog;using Microsoft.Data.SqlClient;namespace MediDesk.Data.Repositories;public sealed class StoreRepository(SqlConnectionFactory f):IStoreRepository{public async Task<PagedResponse<StoreDto>>GetPageAsync(StoreQuery q,CancellationToken ct){var w="IsDeleted=0 AND (@S IS NULL OR Name LIKE @L OR City LIKE @L)";await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand($"SELECT COUNT(1) FROM Stores WHERE {w};SELECT Id,Name,Phone,COALESCE(Address,''),City,State,IsPrimary,IsActive,RowVersion FROM Stores WHERE {w} ORDER BY Name OFFSET @O ROWS FETCH NEXT @P ROWS ONLY",c);cmd.Parameters.Add("@S",SqlDbType.NVarChar,160).Value=(object?)q.Search??DBNull.Value;cmd.Parameters.Add("@L",SqlDbType.NVarChar,170).Value=q.Search is null?DBNull.Value:$"%{q.Search}%";cmd.Parameters.Add("@O",SqlDbType.Int).Value=(q.Page-1)*q.PageSize;cmd.Parameters.Add("@P",SqlDbType.Int).Value=q.PageSize;await using var r=await cmd.ExecuteReaderAsync(ct);await r.ReadAsync(ct);var total=r.GetInt32(0);await r.NextResultAsync(ct);var a=new List<StoreDto>();while(await r.ReadAsync(ct)){var id=r.GetInt64(0);a.Add(new(id,$"STR-{id:0000}",r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetBoolean(6),r.GetBoolean(7),Convert.ToBase64String((byte[])r[8])));}return new(a,q.Page,q.PageSize,total);}public async Task<StoreDto>CreateAsync(CreateStoreRequest x,long u,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand("INSERT Stores(Name,Phone,Address,City,State,CreatedByUserId) OUTPUT INSERTED.Id VALUES(@N,@P,@A,@C,@S,@U)",c);cmd.Parameters.Add("@N",SqlDbType.NVarChar,160).Value=x.Name;cmd.Parameters.Add("@P",SqlDbType.NVarChar,18).Value=x.Phone;cmd.Parameters.Add("@A",SqlDbType.NVarChar,300).Value=(object?)x.Address??DBNull.Value;cmd.Parameters.Add("@C",SqlDbType.NVarChar,100).Value=x.City;cmd.Parameters.Add("@S",SqlDbType.NVarChar,100).Value=x.State;cmd.Parameters.Add("@U",SqlDbType.BigInt).Value=u;var id=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));return (await GetPageAsync(new StoreQuery(PageSize:200),ct)).Items.First(x=>x.Id==id);}}

